from fastapi import FastAPI, Form, UploadFile
from fastapi.testclient import TestClient
from pydantic import Json
from typing import Annotated, List
import pytest

app = FastAPI()

@app.post("/upload")
def upload(
    file: UploadFile,
    tags: Annotated[Json[List[str]], Form()]
):
    return {"file": file.filename, "tags": tags}

client = TestClient(app)

def test_upload():
    # Client sends
    # data = {"items": '["abc", "def"]'}  # JSON string
    # But the field name is 'tags'

    # We need to send as form data
    # tags is a JSON string '["abc", "def"]'
    # file is a file

    files = {"file": ("test.txt", b"content")}
    data = {"tags": '["abc", "def"]'}

    response = client.post("/upload", data=data, files=files)
    print(f"Response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"file": "test.txt", "tags": ["abc", "def"]}

if __name__ == "__main__":
    test_upload()

